// int perfmonctl(int fd, int cmd, void *arg);

int pmu_fd = 4;
int ret;
void *config_ptr = NULL; // Points to pfm structures

// 1. Create perfmon context handle
ret = perfmonctl(pmu_fd, PFM_CREATE_CONTEXT, config_ptr);

// 2. Load configuration registers (PMCs)
// config_ptr points to struct pfm_pmc_attr[]
ret = perfmonctl(pmu_fd, PFM_WRITE_PMCS, config_ptr);

// 3. Start performance counting
ret = perfmonctl(pmu_fd, PFM_START, NULL);

// 4. Retrieve results
// config_ptr points to struct pfm_pmu_read
ret = perfmonctl(pmu_fd, PFM_READ, config_ptr);

// 5. Stop/Cleanup
ret = perfmonctl(pmu_fd, PFM_STOP, NULL);
